            let cycles = if self.cond_passed(opcode >> 28) { arm::execute_arm(self, bus, opcode) } else { 0 };
            self.advance_if_not_branched(instruction_address, 4);
            cycles
        };
        internal_cycles + bus.take_access_cycles()
    }

